	@Inject
	public ShardMLGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pModel = new ModelElements();
		this.pImport = new ImportElements();
		this.pDatabase = new DatabaseElements();
		this.eDatabaseType = new DatabaseTypeElements();
		this.pRelationship = new RelationshipElements();
		this.pHasMany = new HasManyElements();
		this.pHasOne = new HasOneElements();
		this.pBelongsTo = new BelongsToElements();
		this.pShardDecl = new ShardDeclElements();
		this.eStrategy = new StrategyElements();
		this.pRouteRule = new RouteRuleElements();
		this.ePolicy = new PolicyElements();
		this.pQueryPattern = new QueryPatternElements();
		this.eQueryType = new QueryTypeElements();
		this.pWhereClause = new WhereClauseElements();
		this.pWhereCondition = new WhereConditionElements();
		this.eOperator = new OperatorElements();
		this.eLink = new LinkElements();
		this.pSortClause = new SortClauseElements();
		this.eSortOrder = new SortOrderElements();
		this.pGroupBy = new GroupByElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("io.shardml.ShardML".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
